import numpy as np
from scipy.stats import norm


def mad_scale(x):
    x = np.asarray(x, dtype=float)
    return np.median(np.abs(x - np.median(x))) / norm.ppf(0.75)


def trimmed_mean(x, prop):
    x = np.sort(np.asarray(x, dtype=float))
    k = int(prop * len(x))
    return x[k:len(x) - k].mean()


def bisquare_fit(X, y, c=4.685, tol=1e-12, max_iter=500):
    X, y = np.asarray(X, dtype=float), np.asarray(y, dtype=float)
    beta = np.linalg.lstsq(X, y, rcond=None)[0]
    for _ in range(max_iter):
        r = y - X @ beta
        s = np.median(np.abs(r)) / norm.ppf(0.75)
        u = r / (c * s)
        w = np.where(np.abs(u) < 1, (1 - u ** 2) ** 2, 0.0)
        new = np.linalg.solve(X.T @ (w[:, None] * X), X.T @ (w * y))
        if np.max(np.abs(new - beta)) < tol:
            return new, w
        beta = new
    return beta, w
